	v := tea.View{AltScreen: true}
	if m.loadErr != nil {
		v.SetContent(fmt.Sprintf("\n  Failed to load activity: %s\n\n  Press q to quit.\n", m.loadErr))
		return v
	}

	if m.loading {
		v.SetContent(fmt.Sprintf("\n  %s Loading activity...\n", m.spinner.View()))
		return v
	}

	if !m.ready {
		return v
